package com.youngone.mediacontrol.policy.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="policies",uniqueConstraints=@UniqueConstraint(name="uk_policy_version",columnNames="policy_version"))public class Policy{
 @Id private UUID id;@Column(nullable=false,length=150)private String name;@Column(name="policy_version",nullable=false)private long version;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private PolicyStatus status;@Lob @Column(name="payload_json",nullable=false,columnDefinition="LONGTEXT")private String payloadJson;@Column(name="payload_hash",nullable=false,length=64)private String payloadHash;@Lob @Column(nullable=false,columnDefinition="TEXT")private String signature;@Column(name="signing_key_id",nullable=false,length=100)private String signingKeyId;@Column(name="effective_at",nullable=false)private Instant effectiveAt;@Column(name="expires_at")private Instant expiresAt;@Column(name="created_by",nullable=false,length=100)private String createdBy;@Column(name="approved_by",length=100)private String approvedBy;@Column(name="approved_at")private Instant approvedAt;@Column(name="created_at",nullable=false)private Instant createdAt;
 protected Policy(){}public Policy(UUID id,String name,long version,String payloadJson,String payloadHash,String signature,String keyId,Instant effectiveAt,Instant expiresAt,String createdBy,Instant createdAt){this.id=id;this.name=name;this.version=version;this.status=PolicyStatus.DRAFT;this.payloadJson=payloadJson;this.payloadHash=payloadHash;this.signature=signature;this.signingKeyId=keyId;this.effectiveAt=effectiveAt;this.expiresAt=expiresAt;this.createdBy=createdBy;this.createdAt=createdAt;}public void approve(String actor,Instant now){if(createdBy.equals(actor))throw new IllegalArgumentException("Policy creator cannot approve own policy");if(status!=PolicyStatus.DRAFT)throw new IllegalStateException("Only draft policy can be approved");approvedBy=actor;approvedAt=now;status=PolicyStatus.APPROVED;}public void activate(){if(status!=PolicyStatus.APPROVED)throw new IllegalStateException("Policy must be approved");status=PolicyStatus.ACTIVE;}public void retire(){status=PolicyStatus.RETIRED;}public void restoreFromRollback(){status=PolicyStatus.ACTIVE;}public UUID getId(){return id;}public String getName(){return name;}public long getVersion(){return version;}public PolicyStatus getStatus(){return status;}public String getPayloadJson(){return payloadJson;}public String getPayloadHash(){return payloadHash;}public String getSignature(){return signature;}public String getSigningKeyId(){return signingKeyId;}public Instant getEffectiveAt(){return effectiveAt;}public Instant getExpiresAt(){return expiresAt;}public String getCreatedBy(){return createdBy;}public String getApprovedBy(){return approvedBy;}
}
